export * from './schema';

/** Id of the synthetic user that owns the data in the mobile app's local mode. */
export const LOCAL_USER_ID = 'local';

// Built from a variable so Vite does not treat it as an asset URL when the web imports this module.
const moduleUrl = import.meta.url;

/**
 * Absolute path of the SQL migrations generated by drizzle-kit, valid when running from sources
 * (API in development and tests). The API build copies them to `dist/migrations`.
 */
export const MIGRATIONS_FOLDER = fileUrlToPath(new URL('../migrations', moduleUrl));

/**
 * Path of a `file:` URL without `node:url` (this module is also imported by the web): the decoded pathname,
 * without the leading slash of a Windows drive (`/C:/…` → `C:/…`).
 */
export function fileUrlToPath(url: URL): string {
  const path = decodeURIComponent(url.pathname);
  return /^\/[A-Za-z]:\//.test(path) ? path.slice(1) : path;
}
